def normalize(o):
 if isinstance(o,float) and o.is_integer(): return int(o)
 if isinstance(o,list): return [normalize(v) for v in o]
 if isinstance(o,dict): return {k:normalize(v) for k,v in o.items()}
 return o
def digest(o): return hashlib.sha256(json.dumps(normalize(o),ensure_ascii=False,sort_keys=True,separators=(',',':')).encode()).hexdigest()
